from __future__ import absolute_import

from taf.selenium.gnb.oam.coam.vdu.pages import v25R1
from taf.selenium.gnb.oam.coam.vdu import pages
from taf.selenium.gnb.oam.coam.vdu.pages.v22R1 import SnapshotPageViewPanelV22R1
from taf.selenium.gnb.oam.coam.vdu.pages.panels.view import ViewPanel
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Diagnostic(v25R1.Diagnostic):
    def __init__(self, driver, version):
        super(Diagnostic, self).__init__(driver, version)
        self._instance_dict.update({"Snapshot": SnapshotPageV25R3(driver, version),
                                    "Antenna Line Online Monitoring":
                                        AntennaLineOnlineMonitoringPageV25R3(driver, version)})


class SnapshotPageV25R3(pages.SnapshotPage):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'Snapshot', 'Snapshot Collection']

    def __init__(self, driver, version):
        super(SnapshotPageV25R3, self).__init__(driver, version)
        self._view_panel = SnapshotPageViewPanelV25R3(driver, version)

    def collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        return self._view_panel.collect_snapshot(skip_session_renewal, renewal_password, snapshot_waiting_timeout)


class SnapshotPageViewPanelV25R3(SnapshotPageViewPanelV22R1):

    def __init__(self, driver, version):
        self.driver = driver
        super(SnapshotPageViewPanelV25R3, self).__init__(driver, version)

    def _handle_session_renewal_pop_up(self, skip_session_renewal, renewal_password, timeout=5):
        """
        Handles the session renewal pop-up based on the provided arguments.

        :param skip_session_renewal: bool, whether to skip session renewal
        :param renewal_password: str, password for session renewal
        :param timeout: int, timeout for the element to be available
        """
        if self.element_exists(self.locator.SNAPSHOT_DIALOG, timeout):
            if skip_session_renewal:
                self.click_enabled_element(self.locator.CONTINUE_WITH_OUT_RENEWAL_CHECKBOX)
            else:
                self.insert_text_to_enable_element(self.locator.SNAPSHOT_RENEWAL_PASSWORD_INPUT, renewal_password)
                self.click_enabled_element(self.locator.SNAPSHOT_POP_UP_COLLECT)


class AntennaLineOnlineMonitoringPageV25R3(object):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'Antenna Line Online Monitoring']

    def __init__(self, driver, version):
        self._view_panel = AntennaLineOnlineMonitoringPageViewPanelV25R3(driver, version)

    def start_antenna_monitoring(self, antennas, timeout=60):
        self._view_panel.start_antenna_monitoring(antennas, timeout)

    def stop_antenna_monitoring(self, timeout=60):
        self._view_panel.stop_antenna_monitoring(timeout)

    def export_monitoring_data_to_csv(self, timeout=60):
        self._view_panel.export_monitoring_data_to_csv(timeout)


class AntennaLineOnlineMonitoringPageViewPanelV25R3(ViewPanel):

    def __init__(self, driver, version):
        self.driver = driver
        super(AntennaLineOnlineMonitoringPageViewPanelV25R3, self).__init__(driver, version)

    def start_antenna_monitoring(self, antennas, timeout=60):
        """
        Starts monitoring for the specified antennas.

        :param antennas: list, list of antennas to monitor
        :param timeout: int, timeout for the element to be available
        """
        for antenna in antennas:
            self.click_enabled_element(self.locator.ANTENNA_MONITORING_TAB.format(antenna), timeout)
        self.click_enabled_element(self.locator.START_MONITORING_BUTTON, timeout)
        self.wait_for_visibility(self.locator.START_TOAST_MESSAGE_XPATH, timeout)
        self.wait_for_visibility(self.locator.START_TOAST_MESSAGE_SUCCESS_XPATH, timeout)

    def stop_antenna_monitoring(self, timeout=60):
        """
        Stops the antenna monitoring.

        :param timeout: int, timeout for the element to be available
        """
        self.click_enabled_element(self.locator.STOP_MONITORING_BUTTON, timeout)
        self.wait_for_visibility(self.locator.STOP_TOAST_MESSAGE_XPATH, timeout)
        self.wait_for_visibility(self.locator.STOP_TOAST_MESSAGE_SUCCESS_XPATH, timeout)

    def export_monitoring_data_to_csv(self, timeout=60):
        """
        Exports the monitoring data to a CSV file.

        :param timeout: int, timeout for the element to be available
        """
        if self.elements_is_visible(self.locator.EXPORT_TO_CSV_BUTTON, timeout):
            self.click_enabled_element(self.locator.EXPORT_TO_CSV_BUTTON, timeout)
        else:
            raise RuntimeError("Export to CSV button is not visible. Please check")
